package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.accessibilityservice.AccessibilityServiceInfo;import java.util.*;import org.json.*;import org.w3c.dom.*;
/** Additional raw insertion scope: nonzero MultiGeometry part and second inner ring. */
final class VertexInsertionChecks {
 final MapAndroidChecks m;final VertexRotationChecks p;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 VertexInsertionChecks(MapAndroidChecks m){this.m=m;p=new VertexRotationChecks(m);g=new GeometryConfirmationChecks(m);v=p.v;r=p.r;}
 String main(boolean hole){return hole?"1 3 21.5\n1 4 22.5\n2 4 23.5\n1 3 21.5":"20.5 10.5 30.5\n21.5 11.5 31.5\n22.5 12.5 32.5";}
 String expected(boolean hole,boolean before){String first=hole?"1.0 3.0 21.5":"20.5 10.5 30.5",second=hole?"1.0 4.0 22.5":"21.5 11.5 31.5",last=hole?"2.0 4.0 23.5":"22.5 12.5 32.5",point=hole?"1.25 3.5 99.5":"21.25 11.25 99.5";return first+"\n"+(before?point+"\n"+second:second+"\n"+point)+"\n"+last;}
 long fixture(Object store,boolean hole)throws Exception{long id=g.fixture(store,hole);Object doc=r.load(store,id);Element feature=m.element(doc,"point"),shape=(Element)feature.getElementsByTagNameNS("*",hole?"Polygon":"LineString").item(0);feature.removeChild(shape);Element multi=g.child(feature,"MultiGeometry");g.child(g.child(multi,"Point"),"coordinates").setTextContent("9,8,7");multi.appendChild(shape);m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);return id;}
 void identity(long id,boolean hole,boolean before,String token,String stamp)throws Exception{Object d=m.editorField("vertexDraft");m.check(d!=null,"nonzero-part insertion intent retained");Class<?> c=d.getClass();m.check(c.getField("project").getLong(d)==id&&"point".equals(c.getField("feature").get(d))&&m.editorField("VERTEX_SESSION").equals(c.getField("session").get(d))&&(hole?"0.1/inner/1":"0.1").equals(c.getField("key").get(d))&&token.equals(c.getField("token").get(d))&&stamp.equals(c.getField("mainStamp").get(d))&&(before?"before":"after").equals(c.getField("operation").get(d))&&c.getField("index").getInt(d)==1&&!c.getField("addingHole").getBoolean(d),"insertion preserves original owner/process/token/nonzero part/index/operation/main stamp");}
 void scenario(Object store,boolean hole,boolean before)throws Exception{long id=fixture(store,hole);String tag="vertex-insert-"+(hole?"hole":"line")+"-"+(before?"before":"after");try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));p.rotate(UiAutomation.ROTATION_FREEZE_0);m.clickDescription("Выбор геометрии и контура");m.click(hole?"Геометрия 0.1 · внутренний контур 2":"Геометрия 0.1 · LineString");m.geometryReady();m.inputs(main(hole));String token=(String)m.editorField("expected");m.click("Действия");m.click("Редактировать вершины");m.click(hole?"2. 1.0 4.0 22.5":"2. 21.5 11.5 31.5");m.click(before?"Вставить перед":"Вставить после");m.inputs(hole?"1.25 3.5 99.5":"21.25 11.25 99.5");m.runOnMainSync(()->p.field(m.activeDialogRoot()).setSelection(1,3));Object d=m.editorField("vertexDraft");String stamp=(String)d.getClass().getField("mainStamp").get(d);JSONObject raw=p.state();m.check(raw.getInt("start")==1&&raw.getInt("end")==3&&raw.getString("error").isEmpty(),"exact valid insertion raw/selection fixture");identity(id,hole,before,token,stamp);m.check(p.enabled(),"unchanged insertion context permits explicit Apply");v.keyboard();p.snapshot(tag+"-before",true);p.sameRaw(raw);Activity old=m.activity;p.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"insertion Activity actually destroyed in landscape");v.keyboard();p.snapshot(tag+"-land",true);p.sameRaw(raw);identity(id,hole,before,token,stamp);m.check(p.enabled(),"unchanged insertion context permits explicit Apply");old=m.activity;p.rotate(UiAutomation.ROTATION_FREEZE_0);m.check(old!=m.activity&&old.isDestroyed(),"insertion reverse rotation actually recreates Activity");v.keyboard();p.snapshot(tag+"-return",true);p.sameRaw(raw);identity(id,hole,before,token,stamp);m.check(p.enabled(),"unchanged insertion context permits explicit Apply");m.check(m.geometryInput().equals(main(hole))&&Arrays.equals(xml,r.xml(r.load(store,id))),"raw insert/recreate never applies or writes automatically");r.sameAssets(r.load(store,id),assets);
 boolean save=hole?before:!before;if(save){m.click("Применить");m.check(m.geometryInput().equals(expected(hole,before))&&m.editorField("vertexDraft")==null,"explicit Apply inserts at only the chosen side of the chosen vertex");m.check(Arrays.equals(xml,r.xml(r.load(store,id))),"insertion Apply alone never saves KML");p.snapshot(tag+"-applied");p.hideKeyboard();m.click("Сохранить");m.geometryReady();Object expected=r.parse(xml),actual=r.load(store,id);Element f=m.element(expected,"point"),coords;if(hole){Element inner=(Element)f.getElementsByTagNameNS("*","innerBoundaryIs").item(1);coords=(Element)inner.getElementsByTagNameNS("*","coordinates").item(0);coords.setTextContent("3.0,1.0,21.5 3.5,1.25,99.5 4.0,1.0,22.5 4.0,2.0,23.5 3.0,1.0,21.5");}else{Element line=(Element)f.getElementsByTagNameNS("*","LineString").item(0);coords=(Element)line.getElementsByTagNameNS("*","coordinates").item(0);coords.setTextContent("10.5,20.5,30.5 11.5,21.5,31.5 11.25,21.25,99.5 12.5,22.5,32.5");}m.check(m.treeToken(expected).equals(m.treeToken(actual)),"explicit Save changes only addressed nonzero coordinate element, preserving first geometry/other rings/style/media");r.sameAssets(actual,assets);p.ghost();}
 else{m.click("Отмена");m.check(m.geometryInput().equals(main(hole))&&Arrays.equals(xml,r.xml(r.load(store,id))),"Cancel insertion preserves exact dirty main and original KML");r.sameAssets(r.load(store,id),assets);p.snapshot(tag+"-cancelled");p.ghost();m.check(m.geometryInput().equals(main(hole)),"cancelled insertion retains owning private draft across another recreation");}v.emit("VERTEX_INSERT_RESULT kind="+(hole?"hole":"line")+" operation="+(before?"before":"after")+" saved="+save+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(boolean hole:new boolean[]{false,true})for(boolean before:new boolean[]{true,false})scenario(store,hole,before);m.check(m.requests.get()==requests,"nonzero-part insertion makes no tile requests");}finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}}
}
